const ipOf = req => (req.headers['x-forwarded-for'] || req.socket.remoteAddress || '').split(',')[0].trim();
const uaOf = req => String(req.headers['user-agent'] || '').slice(0, 60);
function audit(u, cat, action, prev, next, req) { try { run('INSERT INTO audit(ts,user,cat,action,prev,next,ip) VALUES(?,?,?,?,?,?,?)', new Date().toISOString(), u ? u.id : '-', cat, action, prev == null ? '' : String(prev).slice(0, 300), next == null ? '' : String(next).slice(0, 300), req ? ipOf(req) + ' · ' + uaOf(req) : ''); } catch {} }
const isStaff = u => !!u && (u.is_admin || /^(President|Secretary|Treasurer|Assistant Secretary)$/i.test(u.role || ''));
const isApprover = u => !!u && (u.id === 'admin' || /^(President|Secretary)$/i.test(u.role || ''));
const isTop = u => !!u && (u.id === 'admin' || /^President$/i.test(u.role || ''));
const mname = id => { const m = q1('SELECT name_en FROM members WHERE id=?', id); return m ? m.name_en : id; };
const prof = m => { try { return JSON.parse(m.profile || '{}'); } catch { return {}; } };
const ym = d => String(d || '').slice(0, 7);
