const fmtD = d => { if (!d) return '–'; const t = new Date(d.length === 10 ? d + 'T00:00:00' : d); return isNaN(t) ? d : t.toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' }); };
const num = n => Number(n || 0).toLocaleString('en-US');
const words = n => { n = Math.floor(n); if (!n) return 'Zero'; const a = 'One Two Three Four Five Six Seven Eight Nine Ten Eleven Twelve Thirteen Fourteen Fifteen Sixteen Seventeen Eighteen Nineteen'.split(' '), b = 'Twenty Thirty Forty Fifty Sixty Seventy Eighty Ninety'.split(' '); const w = x => x < 20 ? a[x - 1] : b[Math.floor(x / 10) - 2] + (x % 10 ? ' ' + a[x % 10 - 1] : ''); const h = x => x >= 100 ? a[Math.floor(x / 100) - 1] + ' Hundred' + (x % 100 ? ' ' + w(x % 100) : '') : w(x); let s = ''; const parts = [[10000000, 'Crore'], [100000, 'Lakh'], [1000, 'Thousand']]; for (const [v, nme] of parts) { if (n >= v) { s += h(Math.floor(n / v)) + ' ' + nme + ' '; n %= v; } } if (n) s += h(n); return s.trim(); };
const sel = (name, opts, cur, extra = '') => `<select name="${name}" ${extra}>${opts.map(o => { const [v, l] = Array.isArray(o) ? o : [o, o]; return `<option value="${e(v)}" ${String(v) === String(cur) ? 'selected' : ''}>${e(l)}</option>`; }).join('')}</select>`;
const memberOpts = (all) => q(`SELECT id,name_en,shares FROM members WHERE id!='admin' ${all ? '' : "AND status='active'"} ORDER BY seq`).map(m => [m.id, m.id + ' · ' + m.name_en]);
// accounts
const accFor = method => { const m = String(method || '').toLowerCase(); return m.includes('bank') ? 'Bank Account 01' : m.includes('merchant') ? 'bKash Merchant' : m.includes('bkash') ? 'bKash Merchant' : m.includes('nagad') ? 'Nagad' : 'Cash in Hand'; };
function accPost(name, date, kind, amount, ref, note, by) { const a = q1('SELECT id FROM accounts WHERE name=?', name); if (a) run('INSERT INTO acc_txn(account_id,date,kind,amount,ref,note,by,created) VALUES(?,?,?,?,?,?,?,?)', a.id, date, kind, amount, ref, note || '', by, new Date().toISOString()); }
function accBal() { return q(`SELECT a.*, COALESCE((SELECT SUM(amount) FROM acc_txn WHERE account_id=a.id AND kind IN ('receipt','deposit','transfer_in')),0) rec, COALESCE((SELECT SUM(amount) FROM acc_txn WHERE account_id=a.id AND kind IN ('payment','withdraw','transfer_out','charge')),0) pay FROM accounts a ORDER BY a.id`).map(a => ({ ...a, close: a.opening + a.rec - a.pay })); }
// member dues (FIFO)
function dueState(mid) {
  const dues = q("SELECT * FROM ledger WHERE member_id=? AND debit>0 ORDER BY COALESCE(due_date,date), id", mid);
  let credit = q1('SELECT COALESCE(SUM(credit),0) c FROM ledger WHERE member_id=?', mid).c;
  const t = today(); const out = [];
  for (const d of dues) { const use = Math.min(credit, d.debit); credit -= use; const left = d.debit - use; if (left > 0) { const days = Math.max(0, Math.floor((new Date(t) - new Date(d.due_date || d.date)) / 864e5)); out.push({ ...d, left, days }); } }
  return { open: out, total: out.reduce((s, x) => s + x.left, 0), advance: credit };
}
function allDue() { return q("SELECT id FROM members WHERE id!='admin' AND status='active' ORDER BY seq").map(m => ({ id: m.id, ...dueState(m.id) })); }
// SMS / integrations
const enc = s => { const iv = crypto.randomBytes(12), k = crypto.createHash('sha256').update(secret).digest(); const c = crypto.createCipheriv('aes-256-gcm', k, iv); const x = Buffer.concat([c.update(String(s), 'utf8'), c.final()]); return [iv, c.getAuthTag(), x].map(b => b.toString('base64')).join('.'); };
const dec = s => { try { const [iv, tag, x] = s.split('.').map(b => Buffer.from(b, 'base64')); const k = crypto.createHash('sha256').update(secret).digest(); const d = crypto.createDecipheriv('aes-256-gcm', k, iv); d.setAuthTag(tag); return Buffer.concat([d.update(x), d.final()]).toString('utf8'); } catch { return ''; } };
const integ = () => kvget('integ', { sms: { on: 0, provider: 'BulkSMSBD', mode: 'Live', f: {} }, pay: { on: 0, provider: 'bKash', mode: 'Sandbox', f: {} }, wa: { on: 0, provider: 'Meta WhatsApp Cloud API', mode: 'Sandbox', f: {} } });
const PROV = {
  sms: { title: 'SMS service', hint: 'Sends receipts, reminders and notices.', providers: ['BulkSMSBD', 'Custom HTTP gateway'], fields: [['api_url', 'API URL (custom gateway; use {to} {msg} {key})'], ['api_key', 'API key', 1], ['sender', 'Sender ID']], what: ['Receipt SMS after approval', 'Due reminder and notices', 'OTP for approvals'] },
  pay: { title: 'Payment gateway', hint: 'bKash, Nagad and bank payment callbacks.', providers: ['bKash', 'Nagad', 'SSLCommerz'], fields: [['app_key', 'App key', 1], ['app_secret', 'App secret', 1], ['callback', 'Callback URL (https://api.rbdf.org/v1/callback/pay)']], what: ['Member pays from the portal', 'Callback creates a pending entry', 'Treasurer/approver confirms'] },
  wa: { title: 'WhatsApp', hint: 'Notices and receipts over WhatsApp.', providers: ['Meta WhatsApp Cloud API', 'Bird'], fields: [['token', 'Access token', 1], ['phone_id', 'Phone number ID']], what: ['Send notices', 'Send receipt PDFs'] } };
async function deliver(id) {
  const r = q1('SELECT * FROM sms_log WHERE id=?', id); if (!r || r.status === 'sent') return;
  const i = integ(), s = i.sms; if (!s.on || !s.f.api_key) { run("UPDATE sms_log SET status='queued', err='SMS service not connected' WHERE id=?", id); return; }
  try {
    const key = dec(s.f.api_key); let url;
    if (s.provider === 'BulkSMSBD') url = 'http://bulksmsbd.net/api/smsapi?' + new URLSearchParams({ api_key: key, type: 'text', number: '88' + normMobile(r.to_num), senderid: s.f.sender || '', message: r.msg });
    else url = String(s.f.api_url || '').replace('{to}', encodeURIComponent(normMobile(r.to_num))).replace('{msg}', encodeURIComponent(r.msg)).replace('{key}', encodeURIComponent(key));
    if (!/^https?:\/\//.test(url)) throw new Error('bad url');
    const ctl = new AbortController(); setTimeout(() => ctl.abort(), 15000);
    const resp = await fetch(url, { signal: ctl.signal }); const t = (await resp.text()).slice(0, 120);
    run('UPDATE sms_log SET status=?, err=? WHERE id=?', resp.ok ? 'sent' : 'failed', resp.ok ? '' : t, id);
  } catch (er) { run("UPDATE sms_log SET status='failed', err=? WHERE id=?", String(er.message).slice(0, 120), id); }
}
function queueSms(to, msg, member, channel = 'SMS', sendAt = '') { const r = run('INSERT INTO sms_log(ts,to_num,member_id,msg,channel,status,send_at) VALUES(?,?,?,?,?,?,?)', new Date().toISOString(), to, member || '', msg, channel, 'queued', sendAt); if (!sendAt) deliver(Number(r.lastInsertRowid)); return Number(r.lastInsertRowid); }
setInterval(() => { const n = new Date().toISOString(); q("SELECT id FROM sms_log WHERE status='queued' AND send_at!='' AND send_at<=?", n).forEach(r => deliver(r.id)); }, 60000);
// backups
const BK = DATA + '/backups'; fs.mkdirSync(BK, { recursive: true });
function backupNow(type) { const name = 'rbf-' + new Date().toISOString().replace(/[:.]/g, '-').slice(0, 19) + '.db'; try { db.exec("VACUUM INTO '" + BK + '/' + name + "'"); const sz = fs.statSync(BK + '/' + name).size; run('INSERT INTO backups(ts,type,name,size,status) VALUES(?,?,?,?,?)', new Date().toISOString(), type, name, sz, 'Success'); const all = q('SELECT * FROM backups ORDER BY id DESC').slice(30); all.forEach(b => { try { fs.unlinkSync(BK + '/' + b.name); } catch {} run('DELETE FROM backups WHERE id=?', b.id); }); return name; } catch (er) { run('INSERT INTO backups(ts,type,name,size,status) VALUES(?,?,?,?,?)', new Date().toISOString(), type, '', 0, 'Failed'); return null; } }
setInterval(() => { const t = new Date(Date.now() + 6 * 3600e3); const last = q1("SELECT ts FROM backups WHERE status='Success' ORDER BY id DESC LIMIT 1"); if (!last || Date.now() - new Date(last.ts) > 24 * 3600e3) backupNow('Daily database'); }, 3600e3);
setTimeout(() => { const last = q1("SELECT ts FROM backups WHERE status='Success' ORDER BY id DESC LIMIT 1"); if (!last || Date.now() - new Date(last.ts) > 24 * 3600e3) backupNow('Daily database'); }, 15000);
// approvals
function nextReceipt() { const yy = today().slice(2, 4), n = q1("SELECT COALESCE(MAX(seq),0)+1 n FROM payments WHERE no LIKE ?", `RBF-${yy}-%`).n; return [`RBF-${yy}-${String(n).padStart(4, '0')}`, n]; }
function approvePayment(p, u, req) {
  if (periodClosed(p.paid_on) && cfg().ctl.month_lock) return '!The month ' + ym(p.paid_on) + ' is closed.';
  const [no, seq] = nextReceipt(); const old = p.no;
  run("UPDATE payments SET no=?, seq=?, status='valid', approved_by=? WHERE no=?", no, seq, u.id, old);
  run("INSERT INTO ledger(member_id,date,ref,descr,credit,kind,created) VALUES(?,?,?,?,?,'payment',?)", p.member_id, p.paid_on, no, p.kind, p.amount, new Date().toISOString());
  accPost(accFor(p.method), p.paid_on, 'receipt', p.amount, no, p.kind + ' · ' + p.member_id, u.id);
  if (p.loan_id) { let left = p.amount; q('SELECT * FROM loan_inst WHERE loan_id=? ORDER BY n', p.loan_id).forEach(i => { const need = i.amount - i.paid; if (left > 0 && need > 0) { const x = Math.min(need, left); run('UPDATE loan_inst SET paid=paid+? WHERE loan_id=? AND n=?', x, i.loan_id, i.n); left -= x; } }); const open = q1('SELECT COUNT(*) c FROM loan_inst WHERE loan_id=? AND paid<amount', p.loan_id).c; if (!open) run("UPDATE loans SET status='closed' WHERE id=?", p.loan_id); }
  if (p.project_id) run('INSERT INTO project_inv(project_id,member_id,amount,ref) VALUES(?,?,?,?)', p.project_id, p.member_id, p.amount, no);
  audit(u, 'Payments', 'Approved payment ' + no, old + ' pending', no + ' ' + p.amount, req);
  const m = q1('SELECT * FROM members WHERE id=?', p.member_id);
  if (m && (cfg().ctl.auto_sms || p.sms)) queueSms(m.mobile, `RBF: Receipt ${no}, BDT ${num(p.amount)} received for ${p.kind}. Thank you. Verify: verify.rbdf.org/?r=${no}`, m.id);
  return 'Approved. Receipt ' + no + ' issued.';
}

