  const body = `<div style="max-width:900px;margin:0 auto;padding:24px"><div style="display:flex;align-items:center;gap:14px"><img src="https://rbdf.org/logo.png" style="height:50px"><div><b>Riazuddin Bazar Business Development Forum</b><div class="mut">92 Station Road, Kotwali, Chattogram</div></div></div><h2>${e(rep.title)}</h2><div class="mut">${e(meta)} · Printed ${fmtD(today())}</div><div style="margin-top:12px" class="scroll"><table><tr>${rep.cols.map(c => `<th>${e(c)}</th>`).join('')}</tr>${rep.rows.map(r => `<tr>${r.map(c => `<td>${e(c)}</td>`).join('')}</tr>`).join('')}</table></div><p class="noprint"><button class="btn" onclick="print()">Print / Save as PDF</button></p></div>`;
